#### 2. **Better Approach: Use a Secrets Manager**

For production applications, use a proper secrets manager:

**AWS Secrets Manager Example:**
```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function getSecrets() {
  try {
    const data = await secretsManager.getSecretValue({
      SecretId: 'prod/myapp/secrets'
    }).promise();

    return JSON.parse(data.SecretString);
  } catch (err) {
    throw err;
  }
}

// Initialize app with secrets
let secrets;
getSecrets().then(secrets => {
  // Configure app with retrieved secrets
  process.env.DATABASE_URL = secrets.databaseUrl;
  // Start server after secrets are loaded
});
```

#### 3. **Environment Variable Best Practices**

```javascript
// Validate required environment variables
function validateEnv() {
  const required = ['NODE_ENV', 'PORT'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
}

// Call early in application startup
validateEnv();
```

